<template>
  <section class="flex flex-col gap-6">
    <template v-if="isListRoute">
      <PageTitle :title="activeTabTitle">
        <NuxtLink v-if="showCreateCampaign" :to="createCampaignRoute">
          <Button>Create Campaign</Button>
        </NuxtLink>
      </PageTitle>
      <RecruitmentTabsNav />
    </template>
    <!-- single NuxtPage outside the v-if - two swapped instances break page resolution on back-nav -->
    <NuxtPage />
  </section>
</template>

<script setup lang="ts">
definePageMeta({
  // union of the children's roles - the guard reads child meta, so campaigns stays admin-only
  roles: ['admin', 'manager'],
});

const route = useRoute();
const { isAdmin } = useUserRole();

const isCampaignsRoute = computed(() => route.name === 'recruitment-campaigns');
const isListRoute = computed(() => isCampaignsRoute.value || route.name === 'recruitment-messages');
const activeTabTitle = computed(() => (isCampaignsRoute.value ? 'Campaigns' : 'Messages'));
const showCreateCampaign = computed(() => isAdmin.value && isCampaignsRoute.value);

const createCampaignRoute = { name: 'recruitment-campaigns-create' } as const;
</script>
