<template>
  <FilterTabsNav :items="navigationItems" rounded />
</template>

<script setup lang="ts">
import type { NavigationItem } from '~/types/projects/navigation';

const route = useRoute();
const { userRole } = useUserRole();

// Prefix match (not strict equality like /system/dashboard.vue) because
// recruitment has nested routes (campaigns/[id], campaigns/create) that
// should keep the parent "Campaigns" tab selected.
const tabs: Array<{ label: string; routeName: string; roles: string[] }> = [
  { label: 'Campaigns', routeName: 'recruitment-campaigns', roles: ['admin'] },
  { label: 'Messages', routeName: 'recruitment-messages', roles: ['admin', 'manager'] },
];

function matchesTab(name: string | null | undefined, routeName: string): boolean {
  const current = name?.toString();
  if (!current) return false;
  return current === routeName || current.startsWith(routeName + '-');
}

const navigationItems = computed<NavigationItem[]>(() =>
  tabs
    .filter((tab) => tab.roles.includes(userRole.value))
    .map((tab) => ({
      label: tab.label,
      to: { name: tab.routeName },
      selected: matchesTab(route.name, tab.routeName),
    }))
);
</script>
